<script setup>
import { deviceChoices } from '../../deviceCatalog.js'
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { dutyAll } from '../../duty/api.js'
import { apiAll } from '../../api.js'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { maintenanceAll,maintenanceWrite,maintenanceRevision } from '../../maintenance/api.js'
import { stateLabel,verificationLabel,maintenanceTime,workPayload,verificationPayload,listLines,createAssetRevisionLookup } from '../../maintenance/helpers.js'
import MaintenanceEvidence from './MaintenanceEvidence.vue'
const props=defineProps({items:Array,assets:Array,devices:Array,selected:Object,deviceId:String,assetId:String,correctives:{type:Array,default:()=>[]}})
const emit=defineEmits(['refresh','select','observe','navigate'])
const dialog=ref(''),busy=ref(false),error=ref(''),target=ref(null),key=ref(''),alarms=ref([]),duties=ref([]),links=ref([]),historicalAssets=ref([]),historyLoading=ref(false),historyError=ref(''),formLoading=ref(false)
const form=reactive({}),action=reactive({action:'',reason:'',at:null}),verify=reactive({requiredItems:'',checkedItems:[],result:'PENDING',explanation:'',evidence:[]}),duty=reactive({runId:'',ownerId:'',nextAction:''})
let generation=0,lookupGeneration=0,historyGeneration=0,disposed=false
const showDialog=computed({get:()=>!!dialog.value,set:value=>{if(!value)dialog.value=''}})
const allAssets=computed(()=>[...props.assets,...historicalAssets.value.filter(row=>!props.assets.some(a=>a.id===row.id))])
const rows=computed(()=>props.items.filter(row=>(!props.deviceId||row.deviceIds.includes(props.deviceId))&&(!props.assetId||allAssets.value.find(asset=>asset.id===row.body.assetRevisionId)?.resourceId===props.assetId))),asset=computed(()=>allAssets.value.find(row=>row.id===form.assetRevisionId)),evDevices=computed(()=>deviceChoices(target.value?.deviceIds||asset.value?.deviceIds||[],props.devices)),members=computed(()=>duties.value.find(row=>row.id===duty.runId)?.memberIds||[])
const assetOptions=computed(()=>allAssets.value.filter(row=>row.id===form.assetRevisionId||!props.deviceId||row.deviceIds.includes(props.deviceId)))
const assetName=id=>allAssets.value.find(row=>row.id===id)?.body.name||'固定历史实物'
const lookupAssets=createAssetRevisionLookup(()=>allAssets.value,maintenanceRevision)
async function resolveAssets(ids,isCurrent){const result=await lookupAssets(ids,isCurrent);if(!result)return false;for(const row of result.items)if(!allAssets.value.some(a=>a.id===row.id))historicalAssets.value.push(row);if(result.errors.length)throw Error('固定历史实物资料无法读取，请重试：'+result.errors[0].message);return true}
async function loadRecordAssets(){const token=++historyGeneration;historyLoading.value=true;historyError.value='';try{await resolveAssets([...props.items.map(row=>row.body.assetRevisionId),props.selected?.body.assetRevisionId],()=>token===historyGeneration&&!disposed)}catch(cause){if(token===historyGeneration&&!disposed)historyError.value=cause.message}finally{if(token===historyGeneration&&!disposed)historyLoading.value=false}}
function resetEditor(){generation++;lookupGeneration++;busy.value=false;formLoading.value=false;error.value='';alarms.value=[];duties.value=[];links.value=[]}
async function loadAlarms(){const token=++lookupGeneration;alarms.value=[];const id=asset.value?.body.deviceId;if(!id||!can('menu:alarms'))return;try{const v=await apiAll('/api/v1/alarms?'+new URLSearchParams({deviceId:id}));if(token===lookupGeneration&&!disposed&&dialog.value==='draft')alarms.value=v.items||[]}catch(cause){if(token===lookupGeneration&&!disposed&&dialog.value==='draft')error.value=cause.message}}
async function edit(row){resetEditor();const token=generation;target.value=row;const b=row?.body||{};Object.assign(form,{resourceId:row?.resourceId||createClientId(),expectedVersion:row?.version||0,name:b.name||'',assetRevisionId:b.assetRevisionId||props.assets.find(a=>a.resourceId===props.assetId)?.id||'',type:b.type||'REPAIR',reason:b.reason||'',actions:(b.actions||[]).join('\n'),people:(b.people||[]).join('\n'),parts:(b.parts||[]).join('\n'),faultCycleIds:[...(b.faultCycleIds||[])],correctiveActionId:b.correctiveActionId||''});key.value=createClientId();dialog.value='draft';formLoading.value=true;try{if(await resolveAssets([form.assetRevisionId],()=>token===generation&&!disposed))loadAlarms()}catch(cause){if(token===generation&&!disposed)error.value=cause.message}finally{if(token===generation&&!disposed)formLoading.value=false}}
function beginAction(row,code){resetEditor();target.value=row;Object.assign(action,{action:code,reason:'',at:null});key.value=createClientId();dialog.value='action'}
function beginVerify(row){resetEditor();target.value=row;const v=row.body.verifications?.at(-1);Object.assign(verify,{requiredItems:(v?.requiredItems||[]).join('\n'),checkedItems:[],result:'PENDING',explanation:'',evidence:[]});key.value=createClientId();dialog.value='verification'}
async function beginDuty(row){resetEditor();const token=generation;target.value=row;Object.assign(duty,{runId:'',ownerId:'',nextAction:''});key.value=createClientId();dialog.value='duty';try{const [a,b]=await Promise.all([dutyAll('runs',{status:'ACTIVE'}),maintenanceAll('maintenance-records',row.resourceId,'duty-links')]);if(token!==generation||disposed)return;duties.value=(a.items||[]).filter(r=>r.status==='ACTIVE'&&row.deviceIds.every(id=>r.deviceIds.includes(id)));links.value=b.items||[]}catch(cause){if(token===generation&&!disposed)error.value=cause.message}}
async function save(){if(busy.value||!dialog.value||disposed)return;const token=generation;busy.value=true;error.value='';try{let value;if(dialog.value==='draft'){if(!await resolveAssets([form.assetRevisionId],()=>token===generation&&!disposed))return;value=await maintenanceWrite('maintenance-records','','',workPayload(form,allAssets.value,key.value))}else if(dialog.value==='action'){if(!action.reason.trim())throw Error('请填写实际操作依据');value=await maintenanceWrite('maintenance-records',target.value.resourceId,'actions',{expectedVersion:target.value.version,idempotencyKey:key.value,action:action.action,reason:action.reason.trim(),at:action.at||0})}else if(dialog.value==='verification')value=await maintenanceWrite('maintenance-records',target.value.resourceId,'verifications',verificationPayload(verify,target.value,key.value));else{if(!duty.runId||!duty.ownerId||!duty.nextAction.trim())throw Error('请明确实际值班、负责人和下一步');await maintenanceWrite('maintenance-records',target.value.resourceId,'duty-links',{expectedVersion:target.value.version,runId:duty.runId,ownerId:duty.ownerId,nextAction:duty.nextAction.trim()});value=target.value}if(token!==generation||disposed)return;dialog.value='';emit('refresh');emit('select',value)}catch(cause){if(token===generation&&!disposed)error.value=cause.status===409?'记录版本已变化，请刷新后核对并重试。':cause.message}finally{if(token===generation&&!disposed)busy.value=false}}
watch(()=>[props.items.map(row=>row.body.assetRevisionId).join(','),props.assets.map(row=>row.id).join(','),props.selected?.body.assetRevisionId],loadRecordAssets,{immediate:true})
watch(dialog,(value,previous)=>{if(!value&&previous)resetEditor()},{flush:'sync'})
watch(()=>verify.requiredItems,()=>{verify.checkedItems=verify.checkedItems.filter(item=>listLines(verify.requiredItems).includes(item))})
onBeforeUnmount(()=>{disposed=true;generation++;lookupGeneration++;historyGeneration++})
</script>
<template><section class="maintenance-stack"><div class="maintenance-toolbar"><p class="maintenance-hint">结束工作记录与功能验收独立。人员可登记实际外部参与者；验收人由平台记录当前账号。</p><ui-button v-if="can('POST /api/v1/maintenance-records')" type="primary" size="small" @click="edit()">建立维修记录</ui-button></div><p v-if="historyLoading" class="maintenance-meta">正在读取记录引用的固定实物资料…</p><ui-alert v-if="historyError" :title="historyError" type="error" :closable="false"/><div class="maintenance-table-scroll"><ui-table :data="rows" empty-text="当前实物范围尚无维修记录。"><ui-table-column label="工作 / 实物" min-width="210"><template #default="{row}">{{row.body.name}}<p class="maintenance-meta">{{assetName(row.body.assetRevisionId)}} · {{stateLabel(row.body.type)}} · 版本 {{row.version}}</p></template></ui-table-column><ui-table-column label="工作状态 / 实际起止" min-width="240"><template #default="{row}">{{stateLabel(row.body.status)}}<p class="maintenance-meta">{{maintenanceTime(row.body.startedAt)}} 至 {{maintenanceTime(row.body.endedAt)}}</p></template></ui-table-column><ui-table-column label="独立功能验收" min-width="180"><template #default="{row}">{{verificationLabel(row.body.verifications?.at(-1)?.result||'UNKNOWN')}}<p class="maintenance-meta">{{row.body.verifications?.at(-1)?.verifier}} · {{maintenanceTime(row.body.verifications?.at(-1)?.recordedAt)}}</p></template></ui-table-column><ui-table-column label="操作" min-width="270"><template #default="{row}"><div class="maintenance-actions"><ui-button text size="small" :data-maintenance-record="row.resourceId" @click="emit('select',row)">核对记录</ui-button><ui-button v-if="row.body.status==='DRAFT'&&can('POST /api/v1/maintenance-records')" text size="small" @click="edit(row)">编辑草稿</ui-button><ui-button v-if="row.body.status==='DRAFT'&&can('POST /api/v1/maintenance-records/:id/actions')" text size="small" @click="beginAction(row,'START')">开始工作</ui-button><ui-button v-if="row.body.status==='IN_PROGRESS'&&can('POST /api/v1/maintenance-records/:id/actions')" text size="small" @click="beginAction(row,'COMPLETE')">结束工作</ui-button><ui-button v-if="['DRAFT','IN_PROGRESS'].includes(row.body.status)&&can('POST /api/v1/maintenance-records/:id/actions')" text size="small" @click="beginAction(row,'CANCEL')">取消工作</ui-button><ui-button v-if="['IN_PROGRESS','COMPLETED'].includes(row.body.status)&&can('POST /api/v1/maintenance-records/:id/verifications')" text size="small" @click="beginVerify(row)">登记功能验收</ui-button><ui-button v-if="row.body.status==='COMPLETED'&&can('POST /api/v1/maintenance-records/:id/observations')" text size="small" @click="emit('observe',row)">建立变化观察</ui-button><ui-button v-if="row.body.status!=='CANCELLED'&&can('menu:duty')&&can('POST /api/v1/maintenance-records/:id/duty-links')" text size="small" @click="beginDuty(row)">关联值班事项</ui-button></div></template></ui-table-column></ui-table></div>
<article v-if="selected" class="maintenance-card maintenance-stack"><h3>{{selected.body.name}} · 固定工作版本 {{selected.version}}</h3><p>{{selected.body.reason}}</p><div class="maintenance-grid"><div><h4>实际动作</h4><p v-for="(text,i) in selected.body.actions" :key="i">{{text}}</p><p class="maintenance-meta">人员 {{selected.body.people?.join('、')||'未登记'}} · 配件 {{selected.body.parts?.join('、')||'未登记'}}</p></div><div><h4>实际状态历史</h4><p v-for="(event,i) in selected.body.history" :key="i" class="maintenance-meta">{{event.action}} · {{event.reason}}<br>{{event.actor}} · 实际发生 {{maintenanceTime(event.occurredAt)}} · 平台登记 {{maintenanceTime(event.recordedAt)}}</p></div></div><article v-for="v in selected.body.verifications||[]" :key="v.id" class="maintenance-card"><h4>{{verificationLabel(v.result)}} · {{v.verifier}} · {{maintenanceTime(v.recordedAt)}}</h4><p>{{v.explanation}}</p><p class="maintenance-meta">规定 {{v.requiredItems.join('、')}}<br>实际核验 {{v.checkedItems.join('、')}}</p><MaintenanceEvidence :model-value="v.evidence" :devices="devices.filter(d=>selected.deviceIds.includes(d.id))" readonly @navigate="(name,detail)=>emit('navigate',name,detail)"/></article><ui-empty v-if="!selected.body.verifications?.length" description="工作记录尚无独立功能验收，设备重新在线不能代替验收。"/></article>
<ui-dialog v-model="showDialog" :title="dialog==='draft'?'登记维修工作草稿':dialog==='verification'?'独立功能验收':dialog==='duty'?'关联实际值班事项':'登记实际工作操作'" width="min(900px,94vw)" :close-on-click-modal="false"><div class="maintenance-dialog-body maintenance-stack"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><p v-if="formLoading" class="maintenance-meta">正在读取固定历史实物版本…</p><ui-form label-position="top" :disabled="busy||formLoading"><template v-if="dialog==='draft'"><div class="maintenance-grid"><ui-form-item label="工作名称" required><ui-input v-model="form.name"/></ui-form-item><ui-form-item label="固定实物版本" required><ui-select v-model="form.assetRevisionId" :disabled="!!form.expectedVersion" @change="loadAlarms"><ui-option v-for="a in assetOptions" :key="a.id" :value="a.id" :label="`${a.body.name} · ${a.body.physicalId} · 版本 ${a.version}`"/></ui-select></ui-form-item><ui-form-item label="干预类型" required><ui-select v-model="form.type"><ui-option v-for="t in ['INSPECTION','REPAIR','REPLACEMENT','CALIBRATION','PREVENTIVE']" :key="t" :value="t" :label="stateLabel(t)"/></ui-select></ui-form-item><ui-form-item label="关联实际故障周期"><ui-select v-model="form.faultCycleIds" multiple><ui-option v-for="a in alarms" :key="a.id" :value="a.id" :label="`${a.content||a.alarmType} · ${maintenanceTime(a.timestamp||a.createdAt)}`"/></ui-select></ui-form-item></div><ui-form-item label="实际原因" required><ui-input v-model="form.reason" type="textarea"/></ui-form-item><ui-form-item label="已采取或计划动作（每行一项）"><ui-input v-model="form.actions" type="textarea"/></ui-form-item><ui-form-item label="实际参与人员（每行一位，可含外部人员）"><ui-input v-model="form.people" type="textarea"/></ui-form-item><ui-form-item label="实际配件（每行一项）"><ui-input v-model="form.parts" type="textarea"/></ui-form-item><ui-form-item v-if="correctives.length" label="关联实际整改事项"><ui-select v-model="form.correctiveActionId" clearable><ui-option v-for="c in correctives.filter(c=>asset&&c.deviceIds.includes(asset.body.deviceId))" :key="c.resourceId" :value="c.resourceId" :label="c.body.title"/></ui-select></ui-form-item></template><template v-else-if="dialog==='action'"><p class="maintenance-hint">{{action.action==='COMPLETE'?'此操作仅结束工作记录，功能验收与事项完成需独立登记。':'登记真实操作。未填写实际时间时由服务器登记当前时间。'}}</p><ui-form-item label="实际操作时间（补登记时明确填写）"><ui-date-time v-model="action.at" disable-future/></ui-form-item><ui-form-item label="操作依据" required><ui-input v-model="action.reason" type="textarea"/></ui-form-item></template><template v-else-if="dialog==='verification'"><ui-form-item label="规定功能验收项（每行一项）" required><ui-input v-model="verify.requiredItems" type="textarea"/></ui-form-item><ui-form-item label="实际已核验项"><div class="maintenance-stack"><ui-checkbox v-for="item in listLines(verify.requiredItems)" :key="item" :model-value="verify.checkedItems.includes(item)" @update:model-value="$event?verify.checkedItems.push(item):verify.checkedItems=verify.checkedItems.filter(v=>v!==item)">{{item}}</ui-checkbox></div></ui-form-item><ui-form-item label="功能验收结果" required><ui-select v-model="verify.result"><ui-option v-for="v in ['PENDING','PASSED','FAILED','UNKNOWN']" :key="v" :value="v" :label="verificationLabel(v)"/></ui-select></ui-form-item><ui-form-item label="实际核验结论与依据" required><ui-input v-model="verify.explanation" type="textarea"/></ui-form-item><MaintenanceEvidence v-model="verify.evidence" :devices="evDevices" :disabled="busy"/></template><template v-else><p class="maintenance-hint">维修工作结束不自动完成值班事项。负责人须属于实际进行中值班。</p><ui-form-item label="实际进行中值班" required><ui-select v-model="duty.runId" @change="duty.ownerId=''"><ui-option v-for="r in duties" :key="r.id" :value="r.id" :label="`${maintenanceTime(r.startedAt)} · ${r.leaderId==='admin'?'管理员':r.leaderId||r.leaderUsername||'实际值班'}`"/></ui-select></ui-form-item><ui-form-item label="当班负责人" required><ui-select v-model="duty.ownerId"><ui-option v-for="m in members" :key="m" :value="m" :label="m==='admin'?'管理员':m"/></ui-select></ui-form-item><ui-form-item label="下一步与验收要求" required><ui-input v-model="duty.nextAction" type="textarea"/></ui-form-item><p v-for="link in links" :key="link.id" class="maintenance-meta">已关联 {{link.ownerId}} · {{link.nextAction}}</p></template></ui-form></div><template #footer><ui-button :disabled="busy" @click="dialog=''">取消</ui-button><ui-button type="primary" :loading="busy||formLoading" @click="save">{{dialog==='verification'?'登记独立验收':'保存实际记录'}}</ui-button></template></ui-dialog></section></template>
